WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ['a', 'b']::text[] AS c0, 10.0::float8 AS c1, a1.c3 AS c2 FROM (SELECT * FROM t3 WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS kb)) AS a1 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, '00:00:00.000001'::interval AS c2;
